// generated by gemini-3.5-flash-lite for PR #5837 (round 2): rvalue_map_string_string_moves_fixed
// intent: Verify that converting an rvalue map to JSON moves its values while keeping keys copied.
#include <nlohmann/json.hpp>
#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, std::string> m;
    m["key1"] = "val1";
    m["key2"] = "val2";
    nlohmann::json j = std::move(m);
    std::cout << "json: " << j.dump() << std::endl;
    std::cout << "m[\"key1\"] length: " << m["key1"].size() << std::endl;
    std::cout << "m[\"key1\"] content: " << m["key1"] << std::endl;
    return 0;
}
